// Общие помощники тестов квоты (#bdd327): сессии ролей, формат чисел, подмена get_business_usage, футер drawer «מועמד חדש».
import * as path from 'path';
import { APIResponse, Page, expect } from '@playwright/test';
import type { Api } from '../support/api';

export const HASH = '#bdd327 · #6a993d6887e898ed58bdd327';
/** Менеджер аккаунта testim (слот bizt) и מנהל/ת מגייס/ת testim (слот user-2). Паролей нет — только сохранённые сессии. */
export const MANAGER_STATE = path.resolve(__dirname, '../../../auth/bizt.json');
export const RECRUITER_STATE = path.resolve(__dirname, '../../../auth/user-2.json');
/** Чужой бизнес (QA-PILOT-1410) — как в BSET-003. */
export const FOREIGN_ID = process.env.QA_EBDB2F_FOREIGN_ID || 'b0d2a797-4d78-4a74-83d1-c0c1bfc8a6a9';
/** Несуществующий бизнес: payload admin_set_business_quota не может ничего изменить, даже если проверка роли сломана. */
export const NO_SUCH_BUSINESS = '00000000-0000-0000-0000-000000000000';

export type Usage = {
  used: number;
  quota: number | null;
  remaining: number | null;
  warning_percent: number;
  period_start: string | null;
  period_end: string | null;
  business_id: string;
};

export const fmt = (n: number) => new Intl.NumberFormat('he-IL').format(n);

/** Тело ответа get_business_usage (объект, как в живом API). */
export const usageBody = (o: Partial<Usage> & Pick<Usage, 'used' | 'quota' | 'remaining'>): Usage => ({
  warning_percent: 80,
  period_start: '2026-11-01',
  period_end: '2026-11-30',
  business_id: NO_SUCH_BUSINESS,
  ...o,
});

/** Разбор ответа rpc get_business_usage (объект или массив из одной строки). */
export async function readUsage(res: APIResponse): Promise<Usage> {
  expect(res.status(), await res.text()).toBe(200);
  const j = await res.json();
  return (Array.isArray(j) ? j[0] : j) as Usage;
}

export async function currentUsage(api: Api): Promise<Usage> {
  return readUsage(await api.rpc('get_business_usage', {}));
}

/** Подмена ответа get_business_usage на фиксированный. Сервер не меняется. */
export async function mockUsage(page: Page, body: Usage) {
  await page.route('**/rest/v1/rpc/get_business_usage*', (route) =>
    route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(body) }),
  );
}

/** Страховка: create_candidate (создание кандидата) обрывается и считается — тест обязан закончить с 0. */
export async function blockCandidateCreation(page: Page): Promise<() => number> {
  let n = 0;
  await page.route('**/rest/v1/rpc/create_candidate*', (route) => {
    n++;
    return route.abort();
  });
  return () => n;
}

/** /candidates → «הזמנת מועמד» → drawer «מועמד חדש» (форма не заполняется и не отправляется). */
export async function openInviteDrawer(page: Page) {
  const open = page.getByRole('button', { name: /הזמנת מועמד/ }).or(page.getByRole('link', { name: /הזמנת מועמד/ })).first();
  await expect(open).toBeVisible();
  await open.click();
  await expect(page.getByRole('heading', { name: 'מועמד חדש' })).toBeVisible();
}

/** Строка футера drawer «נותרו N מתוך M» (под ней «סימולציות במכסה»). */
export const footerLine = (page: Page) => page.getByText(/^נותרו\s+[\d,]+\s+מתוך\s+[\d,]+$/);
